        try {
            Token token = tokenizer.parseStringLiteral();
            assertNotNull(token);
            assertEquals(token.getType(), Token.TokenType.STRING_LITERAL);
        } catch (ParseException e) {
            fail("ParseException should not have been thrown");
        }
    }

